// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // 1. wide admissible domain: any non-zero actor, any fundable amount
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        // 2. fund the contract so the selfdestruct beneficiary actually receives value
        vm.deal(address(c), amount);
        address owner = c.smartfix_owner();

        // drive c through sudicideAnyone as the (possibly arbitrary) actor
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // 3. single general rule: either the call reverts (non-owner, funds untouched)
        //    or it succeeds, in which case the CALLER (== owner, enforced by the require)
        //    receives the entire destroyed balance and the contract is emptied.
        assertTrue(
            (ok && actor == owner && actor.balance == amount && address(c).balance == 0)
            || (!ok && actor != owner && address(c).balance == amount)
        );
    }
}

