pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // keep the domain wide but meaningful
        vm.assume(actor != address(0));
        vm.assume(actor != address(this)); // deployer/original owner
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // plain recipient, no receive hooks
        amount = bound(amount, 1, type(uint256).max / 2);

        // re-point the (public, settable) owner at a fuzzed actor
        c.setSmartfix_owner(actor);
        assertEq(c.smartfix_owner(), actor);

        // fund the victim contract so the selfdestruct carries value
        vm.deal(address(c), amount);

        // the (new) owner destroys the contract
        vm.prank(actor);
        c.sudicideAnyone();

        // GENERAL RULE: after any owner-callable sudicideAnyone, the caller
        // (the current owner) is the sole beneficiary: the contract is emptied
        // and the destroyed balance is credited to the caller, not anyone else.
        assertTrue(address(c).balance == 0 && actor.balance == amount);
    }
}

