        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e24);
        bool ok;
        address owner = c.smartfix_owner();
        vm.deal(address(c), amount);
        if (actor == owner) {
            vm.deal(actor, 1);
            vm.prank(actor);
            c.sudicideAnyone();
            ok = true;
