pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // Keep the domain wide: any actor, any reasonable funding amount.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint128).max);

        // Fund the target contract so a successful selfdestruct has value to move.
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        uint256 callerBefore = actor.balance;

        // Drive c through the public entry as the fuzzed actor.
        vm.prank(actor);
        try c.sudicideAnyone() {
            // Rule: only the owner may succeed, and on success the entire
            // balance must be destroyed and credited to the CALLER (msg.sender).
            assertTrue(
                address(c).balance == 0 && actor.balance > callerBefore,
                "successful sudicideAnyone must destroy c and credit the caller"
            );
        } catch {
            // Rule: any non-owner caller must be rejected outright.
            assertTrue(
                actor != c.smartfix_owner(),
                "only the owner may call sudicideAnyone"
            );
        }
    }
}

