contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    c.sudicideAnyone();
    bool ok = true;
    try c.smartfix_owner() returns (address) {
      ok = true;
    } catch {
      ok = false;
    }
    assert(ok);
  }
  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    require(c.smartfix_owner() != address(this));
    bool ok;
    (ok, ) = address(c).call(abi.encodeWithSelector(c.sudicideAnyone.selector));
    assert(!ok);
  }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool isOwner;
        isOwner = (c.smartfix_owner() == address(this));
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        if (isOwner) { assert(!reverted); }
        else { assert(reverted); }
    }
    receive() external payable { }
}

